function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function db():PDO{return $GLOBALS['pdo'];}
function flash(string $text,string $type='ok'):void{$_SESSION['flash']=['text'=>$text,'type'=>$type];}
function logAction(string $action,string $entity,?int $id=null,mixed $before=null,mixed $after=null):void{
 $q=db()->prepare('INSERT INTO audit_logs(actor_id,action,entity,entity_id,before_data,after_data,ip_address) VALUES(?,?,?,?,?,?,?)');
 $q->execute([$_SESSION['user']['id']??null,$action,$entity,$id,$before===null?null:json_encode($before,JSON_UNESCAPED_UNICODE),$after===null?null:json_encode($after,JSON_UNESCAPED_UNICODE),$_SERVER['REMOTE_ADDR']??null]);
}
function can(string $module,string $action='view'):bool{if($module==='inventory'&&$action==='approve'&&currentLocation()!==0)return false;return !empty($_SESSION['user']['permissions']["$module.$action"]);}
function need(string $module,string $action='view'):void{if(!can($module,$action)){http_response_code(403);throw new RuntimeException('Այս բաժնի գործողությունը թույլատրված չէ ձեր դերով։');}}
function go(string $page):never{$parts=explode('&',$page,2);$url='?page='.rawurlencode($parts[0]);if(!empty($parts[1])){$query=[];foreach(explode('&',$parts[1]) as $pair){[$key,$value]=array_pad(explode('=',$pair,2),2,'');$query[rawurldecode($key)]=rawurldecode($value);}$url.='&'.http_build_query($query,'','&',PHP_QUERY_RFC3986);}header('Location: '.$url);exit;}
function token():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function verifyToken():void{if(!hash_equals(token(),(string)($_POST['_token']??'')))throw new RuntimeException('Հարցման անվտանգությունը չի հաստատվել։ Թարմացրեք էջը և կրկին փորձեք։');}
function currentLocation():int{static $location=null;if($location!==null)return $location;$branch=(int)($_SESSION['user']['branch_id']??0);if($branch){$centralId=(int)db()->query("SELECT id FROM branches WHERE code='CENTRAL' LIMIT 1")->fetchColumn();if($branch===$centralId)$branch=0;}return $location=$branch;}
function locations():array{return db()->query("SELECT id,name FROM branches WHERE active=1 AND code<>'CENTRAL' ORDER BY id")->fetchAll(PDO::FETCH_KEY_PAIR);}
function num(float|int|string|null $v):string{return number_format((float)$v,((float)$v==(int)$v?0:3),'.',' ');}
function isAdminUser():bool{return ($_SESSION['user']['role_name']??'')==='admin';}
function documentNo(string $prefix):string{return $prefix.'-'.date('ymd-His').'-'.strtoupper(bin2hex(random_bytes(3)));}
function validDate(string $date):bool{$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$date);return $parsed!==false&&$parsed->format('Y-m-d')===$date;}
function activeLocation(int $id):bool{if($id===0)return true;$active=locations();return isset($active[$id]);}
function val(string $key,mixed $default=''):mixed{return $_POST[$key]??$default;}
function movement(string $type,int $product,?int $lot,?int $from,?int $to,float $qty,float $cost,string $ref,string $reason):void{
 $q=db()->prepare('INSERT INTO movements(movement_no,type,product_id,lot_id,from_location,to_location,qty,unit_cost,reference,reason,actor_id,happened_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,NOW())');
  $q->execute([documentNo('ՇԱՐԺ'),$type,$product,$lot,$from,$to,$qty,$cost,$ref,$reason,$_SESSION['user']['id']]);
}
function downloadCsv(string $filename,array $headers,array $rows):never{header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$headers);foreach($rows as $row)fputcsv($out,$row);fclose($out);exit;}
function zipStoredFiles(array $files):string{$body='';$directory='';foreach($files as $name=>$content){$name=(string)$name;$content=(string)$content;$nameLength=strlen($name);$length=strlen($content);$crc=crc32($content);$offset=strlen($body);$body.=pack('VvvvvvVVVvv',0x04034b50,20,0,0,0,0,$crc,$length,$length,$nameLength,0).$name.$content;$directory.=pack('VvvvvvvVVVvvvvvVV',0x02014b50,20,20,0,0,0,0,$crc,$length,$length,$nameLength,0,0,0,0,0,$offset).$name;}return $body.$directory.pack('VvvvvVVv',0x06054b50,0,0,count($files),count($files),strlen($directory),strlen($body),0);}
function downloadXlsx(string $filename,array $headers,array $rows):never{
 $xmlEscape=static fn(mixed $value):string=>htmlspecialchars((string)$value,ENT_XML1|ENT_QUOTES,'UTF-8');
 $columnName=static function(int $column):string{$name='';while($column>0){$column--;$name=chr(65+$column%26).$name;$column=intdiv($column,26);}return $name;};
 $sheetRows=array_merge([$headers],$rows);$sheet='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>';
 foreach($sheetRows as $ri=>$row){$rowNo=$ri+1;$sheet.='<row r="'.$rowNo.'">';foreach(array_values($row) as $ci=>$value){$ref=$columnName($ci+1).$rowNo;$numericHeader=preg_match('/(քանակ|գին|արժեք|մնացորդ|տարբերություն|օգտագործում|պահանջված|հաստատված|սպառում|օրերի|qty|price|cost|total|average|stock|min|max|optimal)/iu',(string)($headers[$ci]??''));if($ri>0&&$numericHeader&&is_numeric($value))$sheet.='<c r="'.$ref.'"><v>'.(string)(float)$value.'</v></c>';else $sheet.='<c r="'.$ref.'" t="inlineStr"><is><t xml:space="preserve">'.$xmlEscape($value).'</t></is></c>';}$sheet.='</row>';}$sheet.='</sheetData></worksheet>';
 $files=[
  '[Content_Types].xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>',
  '_rels/.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>',
  'xl/workbook.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Հաշվետվություն" sheetId="1" r:id="rId1"/></sheets></workbook>',
  'xl/_rels/workbook.xml.rels'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>',
  'xl/worksheets/sheet1.xml'=>'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'.$sheet,
 ];$bytes=zipStoredFiles($files);header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="'.$filename.'"');header('Content-Length: '.strlen($bytes));echo $bytes;exit;
}
function downloadExport(string $filename,array $headers,array $rows):never{if(($_GET['export']??'')==='xlsx'||($_GET['format']??'')==='xlsx')downloadXlsx(preg_replace('/\.csv$/i','.xlsx',$filename)??'report.xlsx',$headers,$rows);downloadCsv($filename,$headers,$rows);}
function code39Svg(string $value):string{
 $value=strtoupper(trim($value));$alphabet='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ-. $/+%';$encodings=[0x034,0x121,0x061,0x160,0x031,0x130,0x070,0x025,0x124,0x064,0x109,0x049,0x148,0x019,0x118,0x058,0x00D,0x10C,0x04C,0x01C,0x103,0x043,0x142,0x013,0x112,0x052,0x007,0x106,0x046,0x016,0x181,0x0C1,0x1C0,0x091,0x190,0x0D0,0x085,0x184,0x0C4,0x0A8,0x0A2,0x08A,0x02A];
 if($value===''||str_contains($value,'*'))throw new RuntimeException('Պիտակ տպելու համար լրացրեք Code 39-ին համապատասխան շտրիխ կոդ կամ ապրանքի կոդ։');
 $chars='*'.$value.'*';$modules=20+strlen($chars)*13;$x=10;$rects='';
 for($ci=0;$ci<strlen($chars);$ci++){$char=$chars[$ci];$idx=$char==='*'?-1:strpos($alphabet,$char);if($idx===false)throw new RuntimeException('Code 39-ը չի աջակցում «'.$char.'» նիշը։ Օգտագործեք A–Z, 0–9 կամ - . $ / + %։');$pattern=$idx===-1?0x094:$encodings[$idx];for($i=0;$i<9;$i++){$wide=($pattern&(1<<(8-$i)))!==0;$width=$wide?2:1;if($i%2===0)$rects.='<rect x="'.$x.'" y="0" width="'.$width.'" height="46"/>';$x+=$width;}if($ci<strlen($chars)-1)$x++;}
 $width=$modules+20;return '<svg class="barcode-svg" role="img" aria-label="Code 39՝ '.h($value).'" viewBox="0 0 '.$width.' 62" xmlns="http://www.w3.org/2000/svg"><rect width="100%" height="100%" fill="white"/><g fill="#111">'.$rects.'</g><text x="50%" y="59" text-anchor="middle" font-family="Arial,sans-serif" font-size="9">'.h($value).'</text></svg>';
}

