if($page==='products'&&isset($_GET['history'])&&ctype_digit((string)$_GET['history'])){$q=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.active=1');$q->execute([(int)$_GET['history']]);$traceProduct=$q->fetch();if(!$traceProduct){http_response_code(404);exit('Ապրանքը չի գտնվել։');}$loc=currentLocation();$stockSql='SELECT s.*,COALESCE(b.name,"Կենտրոնական պահեստ") location_name,su.name supplier_name FROM stock_lots s LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.product_id=? AND s.qty<>0'.($loc?' AND s.location_id='.$loc:'').' ORDER BY location_name,s.expires_on,s.lot_no';$stockQ=db()->prepare($stockSql);$stockQ->execute([$traceProduct['id']]);$traceLots=$stockQ->fetchAll();$moveSql='SELECT m.*,COALESCE(b1.name,"Կենտրոնական պահեստ") from_name,COALESCE(b2.name,"Կենտրոնական պահեստ") to_name,u.name actor_name,s.lot_no FROM movements m LEFT JOIN branches b1 ON b1.id=m.from_location LEFT JOIN branches b2 ON b2.id=m.to_location LEFT JOIN stock_lots s ON s.id=m.lot_id JOIN users u ON u.id=m.actor_id WHERE m.product_id=?'.($loc?' AND (m.from_location='.$loc.' OR m.to_location='.$loc.')':'').' ORDER BY m.happened_at DESC,m.id DESC';$moveQ=db()->prepare($moveSql);$moveQ->execute([$traceProduct['id']]);$traceMoves=$moveQ->fetchAll();$requestSql='SELECT r.request_no,r.created_at,r.status,r.urgency,b.name branch_name,i.requested_qty,i.approved_qty FROM request_items i JOIN stock_requests r ON r.id=i.request_id JOIN branches b ON b.id=r.branch_id WHERE i.product_id=?'.($loc?' AND r.branch_id='.$loc:'').' ORDER BY r.created_at DESC';$requestQ=db()->prepare($requestSql);$requestQ->execute([$traceProduct['id']]);$traceRequests=$requestQ->fetchAll();header('Content-Type: text/html; charset=UTF-8');?><!doctype html><html lang="hy"><head><meta charset="utf-8"><meta name="csrf-token" content="<?=h(token())?>"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($traceProduct['name'])?> · Ապրանքի հետագիծ</title><link rel="stylesheet" href="assets/app.css?v=20261001-1"></head><body><main class="page"><div class="page-heading"><div class="page-heading-copy"><p class="eyebrow">ԱՊՐԱՆՔԻ ՀԵՏԱԳԻԾ · <?=h($traceProduct['code'])?></p><h1><?=h($traceProduct['name'])?></h1><p class="muted"><?=h($traceProduct['category_name']??'Առանց խմբի')?> · <?=h($traceProduct['unit'])?><?=!empty($traceProduct['manufacturer'])?' · '.h($traceProduct['manufacturer']):''?></p></div><a class="secondary-button" href="?page=products">Վերադառնալ ապրանքներին</a></div><section class="page-card table-card"><div class="card-heading"><div><h2>LOT և ընթացիկ մնացորդ</h2><p>Մուտքի աղբյուր, ժամկետ և պահեստային տեղ</p></div></div><div class="table-scroll"><table><thead><tr><th>Պահեստ</th><th>LOT</th><th>Պիտանի է մինչև</th><th>Մնացորդ</th><?php if(can('purchases','view')):?><th>Գին / ընդհանուր</th><?php endif?><?php if(can('suppliers','view')):?><th>Մատակարար</th><?php endif?><th>Տեղ</th></tr></thead><tbody><?php if(!$traceLots):?><tr><td colspan="7" class="empty-state">Ընթացիկ LOT մնացորդ չկա։</td></tr><?php else:foreach($traceLots as $lot):?><tr><td><?=h($lot['location_name'])?></td><td><?=h($lot['lot_no'])?></td><td><?=h($lot['expires_on']??'—')?></td><td><b><?=num($lot['qty'])?> <?=h($traceProduct['unit'])?></b></td><?php if(can('purchases','view')):?><td><?=num($lot['unit_cost'])?> ֏ <small><?=num((float)$lot['qty']*(float)$lot['unit_cost'])?> ֏</small></td><?php endif?><?php if(can('suppliers','view')):?><td><?=h($lot['supplier_name']??'—')?></td><?php endif?><td><?=h($lot['bin_location']??'—')?></td></tr><?php endforeach;endif?></tbody></table></div></section><section class="page-card table-card"><div class="card-heading"><div><h2>Պահեստի շարժեր</h2><p>Վերջին 200 գրանցումները՝ ներառյալ ուղղիչ շարժերը</p></div></div><div class="table-scroll"><table><thead><tr><th>Ամսաթիվ</th><th>Փաստաթուղթ</th><th>Գործողություն</th><th>LOT</th><th>Պահեստից</th><th>Ուր</th><th>Քանակ</th><th>Կատարող</th><th>Պատճառ</th></tr></thead><tbody><?php if(!$traceMoves):?><tr><td colspan="9" class="empty-state">Շարժերի պատմություն դեռ չկա։</td></tr><?php else:foreach($traceMoves as $move):?><tr><td><?=h(date('d.m.Y H:i',strtotime($move['happened_at'])))?></td><td><?=h($move['reference']?:$move['movement_no'])?></td><td><?=h($move['type'])?></td><td><?=h($move['lot_no']??'—')?></td><td><?=h($move['from_name'])?></td><td><?=h($move['to_name'])?></td><td><?=num($move['qty'])?></td><td><?=h($move['actor_name'])?></td><td><?=h($move['reason']??'—')?></td></tr><?php endforeach;endif?></tbody></table></div></section><section class="page-card table-card"><div class="card-heading"><div><h2>Մասնաճյուղերի պահանջներ</h2><p>Պահանջված և հաստատված քանակները</p></div></div><div class="table-scroll"><table><thead><tr><th>Համար</th><th>Ամսաթիվ</th><th>Մասնաճյուղ</th><th>Կարգավիճակ</th><th>Պահանջված</th><th>Հաստատված</th></tr></thead><tbody><?php if(!$traceRequests):?><tr><td colspan="6" class="empty-state">Պահանջագրերի տվյալներ դեռ չկան։</td></tr><?php else:foreach($traceRequests as $request):?><tr><td><?=h($request['request_no'])?></td><td><?=h(date('d.m.Y',strtotime($request['created_at'])))?></td><td><?=h($request['branch_name'])?></td><td><?=pill($request['status'])?></td><td><?=num($request['requested_qty'])?></td><td><?=num($request['approved_qty'])?></td></tr><?php endforeach;endif?></tbody></table></div></section></main></body></html><?php exit;}if($page==='products'&&in_array((string)($_GET['export']??''),['csv','xlsx'],true)){$location=currentLocation();$sql='SELECT p.code,p.name,c.name category_name,p.manufacturer,p.unit,COALESCE(s.name,rs.name) supplier_name,COALESCE(NULLIF(p.purchase_price,0),recent.unit_cost,0) purchase_price,COALESCE(stock.qty,0) qty,p.min_qty,p.optimal_qty,p.max_qty FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN (SELECT product_id,MAX(received_on) last_received FROM stock_lots GROUP BY product_id) recent_date ON recent_date.product_id=p.id LEFT JOIN stock_lots recent ON recent.product_id=p.id AND recent.received_on=recent_date.last_received LEFT JOIN suppliers rs ON rs.id=recent.supplier_id LEFT JOIN (SELECT product_id,SUM(qty) qty FROM stock_lots'.($location?' WHERE location_id='.$location:'').' GROUP BY product_id) stock ON stock.product_id=p.id WHERE p.active=1';$params=[];if(!empty($_GET['supplier_id'])&&ctype_digit((string)$_GET['supplier_id'])){$sql.=' AND (p.supplier_id=? OR EXISTS(SELECT 1 FROM stock_lots sl WHERE sl.product_id=p.id AND sl.supplier_id=?))';$params[]=(int)$_GET['supplier_id'];$params[]=(int)$_GET['supplier_id'];}if(trim((string)($_GET['barcode']??''))!==''){$sql.=' AND (p.barcode=? OR p.code=?)';$barcode=trim((string)$_GET['barcode']);$params[]=$barcode;$params[]=$barcode;}$sql.=' GROUP BY p.id';if(($_GET['view']??'')==='low')$sql.=' HAVING qty<=p.min_qty';$sql.=' ORDER BY p.name';$q=db()->prepare($sql);$q->execute($params);$rows=array_map(static fn($r)=>[$r['code'],$r['name'],$r['category_name'],$r['manufacturer'],$r['unit'],$r['supplier_name'],$r['purchase_price'],$r['qty'],$r['min_qty'],$r['optimal_qty'],$r['max_qty']],$q->fetchAll());downloadExport('diagen-products.csv',['Կոդ','Ապրանք','Խումբ','Արտադրող','Միավոր','Մատակարար','Գին','Մնացորդ','MIN','OPTIMAL','MAX'],$rows);}if(in_array((string)($_GET['export']??''),['csv','xlsx'],true)&&in_array($page,['stock','expiry','requests','returns','inventory','receipts','purchases'],true)){
 if($page==='receipts'){$sql='SELECT r.receipt_no,r.received_on,po.order_no,s.name supplier_name,r.invoice_no,r.contract_no,p.code,p.name product_name,sl.lot_no,sl.expires_on,ri.qty,ri.unit_cost,u.name actor_name FROM receipt_items ri JOIN receipts r ON r.id=ri.receipt_id LEFT JOIN purchase_orders po ON po.id=r.purchase_order_id JOIN suppliers s ON s.id=r.supplier_id JOIN users u ON u.id=r.received_by JOIN products p ON p.id=ri.product_id LEFT JOIN stock_lots sl ON sl.id=ri.lot_id WHERE 1=1'.(currentLocation()?' AND sl.location_id='.currentLocation():'').' ORDER BY r.received_on DESC,r.id DESC,ri.id';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['receipt_no'],$r['order_no'],$r['received_on'],$r['supplier_name'],$r['invoice_no'],$r['contract_no'],$r['code'],$r['product_name'],$r['lot_no'],$r['expires_on'],$r['qty'],$r['unit_cost'],$r['actor_name']],$rows);downloadExport('diagen-receipts.csv',['Մուտքի փաստաթուղթ','Պատվեր','Ամսաթիվ','Մատակարար','Հաշիվ','Պայմանագիր','Կոդ','Ապրանք','LOT','Ժամկետ','Քանակ','Միավորի գին','Ընդունող'],$data);}
 if($page==='purchases'){$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');if(!validDate($from)||!validDate($to)||$from>$to)throw new RuntimeException('Հաշվետվության ամսաթվերը սխալ են։');$q=db()->prepare('SELECT po.order_no,po.ordered_on,po.expected_on,po.status,po.note,s.name supplier_name,p.code,p.name product_name,i.ordered_qty,i.received_qty,i.unit_cost,(i.ordered_qty*i.unit_cost) total,u.name actor_name FROM purchase_orders po JOIN suppliers s ON s.id=po.supplier_id JOIN purchase_order_items i ON i.purchase_order_id=po.id JOIN products p ON p.id=i.product_id JOIN users u ON u.id=po.created_by WHERE po.ordered_on BETWEEN ? AND ?'.(isset($_GET['supplier_id'])&&ctype_digit((string)$_GET['supplier_id'])?' AND po.supplier_id='.(int)$_GET['supplier_id']:'').' ORDER BY po.ordered_on DESC,po.id DESC');$q->execute([$from,$to]);$rows=$q->fetchAll();$data=array_map(fn($r)=>[$r['order_no'],$r['ordered_on'],$r['expected_on'],$r['supplier_name'],$r['code'],$r['product_name'],$r['ordered_qty'],$r['received_qty'],$r['unit_cost'],$r['total'],$r['status'],$r['actor_name'],$r['note']],$rows);downloadExport('diagen-purchases.csv',['Պատվեր','Ամսաթիվ','Սպասվող առաքում','Մատակարար','Կոդ','Ապրանք','Պատվիրած','Ստացված','Միավորի գին','Ընդհանուր','Կարգավիճակ','Պատվիրող','Նշում'],$data);}
 if($page==='stock'&&($_GET['view']??'')==='matrix'){$locations=db()->query('SELECT id,name FROM branches WHERE active=1 AND code<>\'CENTRAL\''. (currentLocation()?' AND id='.currentLocation():'').' ORDER BY id')->fetchAll();if(!currentLocation())array_unshift($locations,['id'=>0,'name'=>'Կենտրոնական պահեստ']);$products=db()->query('SELECT id,code,name,unit FROM products WHERE active=1 ORDER BY name')->fetchAll();$qty=db()->query('SELECT product_id,location_id,SUM(qty) qty FROM stock_lots WHERE qty>0'.(currentLocation()?' AND location_id='.currentLocation():'').' GROUP BY product_id,location_id')->fetchAll();$map=[];foreach($qty as $row)$map[(int)$row['product_id']][(int)$row['location_id']]=(float)$row['qty'];$headers=array_merge(['Կոդ','Ապրանք','Միավոր'],array_column($locations,'name'),['Ընդամենը']);$data=[];foreach($products as $product){$line=[$product['code'],$product['name'],$product['unit']];$sum=0;foreach($locations as $loc){$value=$map[(int)$product['id']][(int)$loc['id']]??0;$line[]=$value;$sum+=$value;}$line[]=$sum;$data[]=$line;}downloadExport('diagen-stock-matrix.csv',$headers,$data);}
 if($page==='stock'){$sql='SELECT COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,c.name category_name,s.lot_no,s.expires_on,s.qty,p.unit,s.unit_cost,(s.qty*s.unit_cost) total_value,s.bin_location,su.name supplier_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty<>0'.(currentLocation()?' AND s.location_id='.currentLocation():'').' ORDER BY location_name,p.name,s.expires_on';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['location_name'],$r['code'],$r['product_name'],$r['category_name'],$r['lot_no'],$r['expires_on'],$r['qty'],$r['unit'],$r['unit_cost'],$r['total_value'],$r['bin_location'],$r['supplier_name']],$rows);downloadExport('diagen-stock.csv',['Պահեստ','Կոդ','Ապրանք','Խումբ','LOT','Ժամկետ','Քանակ','Միավոր','Միավորի գին','Ընդհանուր արժեք','Պահեստային տեղ','Մատակարար'],$data);}
 if($page==='expiry'){$sql='SELECT COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,s.lot_no,s.qty,s.expires_on,DATEDIFF(s.expires_on,CURDATE()) days_left,su.name supplier_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id LEFT JOIN suppliers su ON su.id=s.supplier_id WHERE s.qty>0 AND s.expires_on IS NOT NULL'.(currentLocation()?' AND s.location_id='.currentLocation():'').' ORDER BY s.expires_on';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['location_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['qty'],$r['expires_on'],$r['days_left'],$r['supplier_name']],$rows);downloadExport('diagen-expiry.csv',['Պահեստ','Կոդ','Ապրանք','LOT','Քանակ','Ժամկետ','Օրերի տարբերություն','Մատակարար'],$data);}
 if($page==='requests'){$sql='SELECT r.request_no,r.created_at,b.name branch_name,u.name requested_by,r.status,r.urgency,r.reason,p.code,p.name product_name,i.requested_qty,i.approved_qty FROM stock_requests r JOIN branches b ON b.id=r.branch_id JOIN users u ON u.id=r.requested_by JOIN request_items i ON i.request_id=r.id JOIN products p ON p.id=i.product_id'.(currentLocation()?' WHERE r.branch_id='.currentLocation():'').' ORDER BY r.created_at DESC';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['request_no'],$r['created_at'],$r['branch_name'],$r['requested_by'],$r['status'],$r['urgency'],$r['reason'],$r['code'],$r['product_name'],$r['requested_qty'],$r['approved_qty']],$rows);downloadExport('diagen-requests.csv',['Պահանջագիր','Ամսաթիվ','Մասնաճյուղ','Հայցող','Կարգավիճակ','Հրատապություն','Հիմնավորում','Կոդ','Ապրանք','Պահանջված','Հաստատված'],$data);}
 if($page==='returns'){$sql='SELECT r.return_no,r.created_at,r.direction,COALESCE(b.name,\'Կենտրոնական պահեստ\') source_name,su.name supplier_name,p.code,p.name product_name,sl.lot_no,r.qty,r.reason,u.name actor_name FROM returns r JOIN products p ON p.id=r.product_id LEFT JOIN stock_lots sl ON sl.id=r.lot_id LEFT JOIN branches b ON b.id=r.from_location LEFT JOIN suppliers su ON su.id=r.supplier_id JOIN users u ON u.id=r.actor_id'.(currentLocation()?' WHERE r.from_location='.currentLocation():'').' ORDER BY r.created_at DESC';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['return_no'],$r['created_at'],$r['direction'],$r['source_name'],$r['supplier_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['qty'],$r['reason'],$r['actor_name']],$rows);downloadExport('diagen-returns.csv',['Փաստաթուղթ','Ամսաթիվ','Ուղղություն','Պահեստ','Մատակարար','Կոդ','Ապրանք','LOT','Քանակ','Պատճառ','Կատարող'],$data);}
 if($page==='inventory'){$sql='SELECT i.inventory_no,i.status,i.started_at,i.closed_at,COALESCE(b.name,\'Կենտրոնական պահեստ\') location_name,p.code,p.name product_name,sl.lot_no,l.expected_qty,l.counted_qty,(COALESCE(l.counted_qty,0)-l.expected_qty) difference,l.difference_reason FROM inventory_lines l JOIN inventory_sessions i ON i.id=l.session_id JOIN products p ON p.id=l.product_id LEFT JOIN stock_lots sl ON sl.id=l.lot_id LEFT JOIN branches b ON b.id=i.location_id'.(currentLocation()?' WHERE i.location_id='.currentLocation():'').' ORDER BY i.started_at DESC,p.name';$rows=db()->query($sql)->fetchAll();$data=array_map(fn($r)=>[$r['inventory_no'],$r['status'],$r['started_at'],$r['closed_at'],$r['location_name'],$r['code'],$r['product_name'],$r['lot_no'],$r['expected_qty'],$r['counted_qty'],$r['difference'],$r['difference_reason']],$rows);downloadExport('diagen-inventory.csv',['Գույքագրում','Կարգավիճակ','Սկսվել է','Փակվել է','Պահեստ','Կոդ','Ապրանք','LOT','Հաշվառված','Փաստացի','Տարբերություն','Պատճառ'],$data);}
