$products=db()->query('SELECT p.*,c.name category_name,s.name supplier_name,(SELECT su.name FROM stock_lots sl JOIN suppliers su ON su.id=sl.supplier_id WHERE sl.product_id=p.id ORDER BY sl.received_on DESC,sl.id DESC LIMIT 1) recent_supplier_name,(SELECT sl.unit_cost FROM stock_lots sl WHERE sl.product_id=p.id ORDER BY sl.received_on DESC,sl.id DESC LIMIT 1) recent_purchase_price FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN suppliers s ON s.id=p.supplier_id WHERE p.active=1 ORDER BY p.name')->fetchAll();
$branches=locations();$suppliers=db()->query('SELECT id,name FROM suppliers WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_KEY_PAIR);$activeUsers=db()->query('SELECT id,name FROM users WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_KEY_PAIR);$roles=db()->query('SELECT id,title FROM roles ORDER BY title')->fetchAll(PDO::FETCH_KEY_PAIR);$cats=db()->query('SELECT c.id,IF(c.parent_id IS NULL,c.name,CONCAT(p.name,\' / \',c.name)) label FROM categories c LEFT JOIN categories p ON p.id=c.parent_id ORDER BY COALESCE(p.name,c.name),c.parent_id,c.name')->fetchAll(PDO::FETCH_KEY_PAIR);
$location=currentLocation();$canSeeCostData=!$location&&(can('reports','view')||can('purchases','view'));$stockWhere=$location?' WHERE location_id='.$location:'';$totalQty=(float)db()->query('SELECT COALESCE(SUM(qty),0) FROM stock_lots'.$stockWhere)->fetchColumn();$totalValue=(float)db()->query('SELECT COALESCE(SUM(qty*unit_cost),0) FROM stock_lots'.$stockWhere)->fetchColumn();$reservedQty=$location?0:(float)db()->query("SELECT COALESCE(SUM(ri.approved_qty),0) FROM request_items ri JOIN stock_requests r ON r.id=ri.request_id WHERE r.status IN ('approved','partially_approved','collecting','ready_to_ship')")->fetchColumn();$freeQty=max(0,$totalQty-$reservedQty);$lowStockSub=$location?' WHERE location_id='.$location:'';$lowCount=(int)db()->query('SELECT COUNT(*) FROM products p LEFT JOIN (SELECT product_id,SUM(qty) qty FROM stock_lots'.$lowStockSub.' GROUP BY product_id) s ON s.product_id=p.id WHERE p.active=1 AND COALESCE(s.qty,0)<=p.min_qty')->fetchColumn();$expiredCount=(int)db()->query('SELECT COUNT(*) FROM stock_lots WHERE qty>0 AND expires_on<CURDATE()'.($location?' AND location_id='.$location:''))->fetchColumn();$nearCount=(int)db()->query('SELECT COUNT(*) FROM stock_lots WHERE qty>0 AND expires_on BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 90 DAY)'.($location?' AND location_id='.$location:''))->fetchColumn();$openRequests=(int)db()->query("SELECT COUNT(*) FROM stock_requests WHERE status IN ('sent','review','approved','partially_approved','collecting','ready_to_ship','shipped','received')".($location?' AND branch_id='.$location:''))->fetchColumn();$pendingRequests=(int)db()->query("SELECT COUNT(*) FROM stock_requests WHERE status IN ('sent','review')".($location?' AND branch_id='.$location:''))->fetchColumn();$awaitingReceiptCount=(int)db()->query("SELECT COUNT(*) FROM stock_requests WHERE status='shipped'".($location?' AND branch_id='.$location:''))->fetchColumn();$zeroCount=(int)db()->query('SELECT COUNT(*) FROM products p WHERE p.active=1 AND NOT EXISTS (SELECT 1 FROM stock_lots s WHERE s.product_id=p.id AND s.location_id=' . (int)$location . ' AND s.qty>0)')->fetchColumn();
$notifications=[];$addNotice=function(string $title,string $detail,string $link,string $tone='amber')use(&$notifications){$notifications[]=['title'=>$title,'detail'=>$detail,'link'=>$link,'tone'=>$tone];};
if(can('stock','view')){$q=db()->query('SELECT p.id,p.code,p.name,p.min_qty,COALESCE(SUM(s.qty),0) qty FROM products p LEFT JOIN stock_lots s ON s.product_id=p.id'.($location?' AND s.location_id='.$location:'').' WHERE p.active=1 GROUP BY p.id HAVING qty<=p.min_qty ORDER BY qty,p.name');foreach($q->fetchAll() as $n)$addNotice((float)$n['qty']<=0?'Ապրանքը զրոյական մնացորդ ունի':'Պահանջվում է գնում կատարել',$n['code'].' · '.$n['name'].' · մնացորդ՝ '.num($n['qty']).' / MIN '.num($n['min_qty']),'?page=stock',(float)$n['qty']<=0?'red':'amber');$maxQ=db()->query('SELECT p.code,p.name,p.max_qty,COALESCE(SUM(s.qty),0) qty FROM products p LEFT JOIN stock_lots s ON s.product_id=p.id'.($location?' AND s.location_id='.$location:'').' WHERE p.active=1 AND p.max_qty>0 GROUP BY p.id HAVING qty>p.max_qty ORDER BY qty DESC');foreach($maxQ->fetchAll() as $n)$addNotice('Պաշարը գերազանցում է առավելագույն շեմը',$n['code'].' · '.$n['name'].' · մնացորդ՝ '.num($n['qty']).' / MAX '.num($n['max_qty']),'?page=stock','violet');}
if(can('expiry','view')){$q=db()->query('SELECT s.id,s.lot_no,s.qty,s.expires_on,p.code,p.name,DATEDIFF(s.expires_on,CURDATE()) days_left,b.name branch_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id WHERE s.qty>0 AND s.expires_on IS NOT NULL AND s.expires_on<=DATE_ADD(CURDATE(),INTERVAL 180 DAY)'.($location?' AND s.location_id='.$location:'').' ORDER BY s.expires_on');foreach($q->fetchAll() as $n){$days=(int)$n['days_left'];$label=$days<0?'Ժամկետանց ապրանք':($days<=7?'Պիտանելիության ժամկետին մնացել է մինչև 7 օր':($days<=30?'Պիտանելիության ժամկետին մնացել է մինչև 30 օր':($days<=60?'Պիտանելիության ժամկետին մնացել է մինչև 60 օր':($days<=90?'Պիտանելիության ժամկետին մնացել է մինչև 90 օր':'Պիտանելիության ժամկետին մնացել է մինչև 180 օր'))));$addNotice($label,$n['code'].' · '.$n['name'].' · LOT '.$n['lot_no'].' · '.($n['branch_name']??'Կենտրոնական պահեստ').' · '.num($n['qty']).' հատ','?page=expiry',$days<0?'red':($days<=30?'amber':'blue'));}}
if(can('requests','view')){$reqSql="SELECT r.request_no,r.status,r.created_at,b.name branch_name FROM stock_requests r JOIN branches b ON b.id=r.branch_id WHERE r.status IN ('sent','review')".($location?' AND r.branch_id='.$location:'').' ORDER BY r.id DESC';if($location||can('requests','approve')){$requestNoticeTitle=$location?'Ձեր պահանջագիրը սպասում է ստուգման':'Նոր մասնաճյուղային պահանջագիր';foreach(db()->query($reqSql)->fetchAll() as $n)$addNotice($requestNoticeTitle,$n['request_no'].' · '.$n['branch_name'].' · ստուգման սպասող','?page=requests','blue');}}
if($location&&can('requests','view')){$shipSql="SELECT r.request_no,r.sent_at,b.name branch_name FROM stock_requests r JOIN branches b ON b.id=r.branch_id WHERE r.status='shipped' AND r.branch_id=".(int)$location.' ORDER BY r.sent_at';foreach(db()->query($shipSql)->fetchAll() as $n)$addNotice('Սպասվում է ստացման հաստատում',$n['request_no'].' · ուղարկվել է '.date('d.m.Y',strtotime($n['sent_at'])),'?page=requests','violet');}
if(can('inventory','view')){if($location){$inventorySql="SELECT i.inventory_no,i.status,i.started_at,b.name branch_name FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id WHERE i.status IN ('open','counted') AND i.location_id=".(int)$location.' ORDER BY i.started_at';}elseif(can('inventory','approve')){$inventorySql="SELECT i.inventory_no,i.status,i.started_at,b.name branch_name FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id WHERE i.status='counted' ORDER BY i.started_at";}else{$inventorySql="SELECT i.inventory_no,i.status,i.started_at,b.name branch_name FROM inventory_sessions i LEFT JOIN branches b ON b.id=i.location_id WHERE i.status='open' AND i.location_id=0 ORDER BY i.started_at";}foreach(db()->query($inventorySql)->fetchAll() as $n)$addNotice($n['status']==='counted'?'Հաստատման սպասող գույքագրում':'Գույքագրումը դեռ բաց է',$n['inventory_no'].' · '.($n['branch_name']??'Կենտրոնական պահեստ').' · սկսվել է '.date('d.m.Y',strtotime($n['started_at'])),'?page=inventory',$n['status']==='counted'?'violet':'amber');}
if($location&&can('requests','view')){$recentRequests=db()->prepare("SELECT r.request_no,r.status,r.rejection_reason FROM stock_requests r JOIN (SELECT entity_id,MAX(created_at) changed_at FROM audit_logs WHERE entity='stock_requests' AND entity_id IS NOT NULL GROUP BY entity_id) changes ON changes.entity_id=r.id AND changes.changed_at>=DATE_SUB(NOW(),INTERVAL 7 DAY) WHERE r.branch_id=? AND r.status IN ('approved','partially_approved','rejected','received') ORDER BY changes.changed_at DESC LIMIT 10");$recentRequests->execute([$location]);foreach($recentRequests->fetchAll() as $n){$status=$n['status'];$title=$status==='rejected'?'Պահանջագիրը մերժվել է':(in_array($status,['approved','partially_approved'],true)?'Պահանջագիրը հաստատվել է':'Պահանջագրի ընթացքը թարմացվել է');$detail=$n['request_no'].' · '.($n['rejection_reason']?:pill($status));$addNotice($title,strip_tags($detail),'?page=requests',$status==='rejected'?'red':'green');}}
if(!$location&&can('transfers','view')&&can('transfers','approve')){$pendingTransfers=db()->query("SELECT t.transfer_no,b1.name from_name,b2.name to_name FROM transfers t JOIN branches b1 ON b1.id=t.from_branch JOIN branches b2 ON b2.id=t.to_branch WHERE t.status='pending' ORDER BY t.id DESC LIMIT 10");foreach($pendingTransfers->fetchAll() as $n)$addNotice('Հաստատման սպասող տեղափոխում',$n['transfer_no'].' · '.$n['from_name'].' → '.$n['to_name'],'?page=transfers','blue');}
if($location&&can('transfers','view')){$incomingTransfers=db()->prepare("SELECT t.transfer_no,b.name from_name FROM transfers t JOIN branches b ON b.id=t.from_branch WHERE t.status='shipped' AND t.to_branch=? ORDER BY t.id DESC LIMIT 10");$incomingTransfers->execute([$location]);foreach($incomingTransfers->fetchAll() as $n)$addNotice('Սպասվում է տեղափոխման ընդունում',$n['transfer_no'].' · ուղարկել է '.$n['from_name'],'?page=transfers','violet');}if(!can('notifications','view'))$notifications=[];$notificationReadKeys=[];$notificationUserId=(int)($_SESSION['user']['id']??0);if($notificationUserId&&$notifications){$notificationKeys=array_map(static fn(array $item):string=>sha1($item['title'].'|'.$item['detail'].'|'.$item['link']),$notifications);$marks=implode(',',array_fill(0,count($notificationKeys),'?'));$readQuery=db()->prepare("SELECT notice_key FROM user_notification_reads WHERE user_id=? AND notice_key IN ($marks)");$readQuery->execute([$notificationUserId,...$notificationKeys]);$notificationReadKeys=array_fill_keys($readQuery->fetchAll(PDO::FETCH_COLUMN),true);}$notificationCount=count(array_filter($notifications,static fn(array $item):bool=>!isset($notificationReadKeys[sha1($item['title'].'|'.$item['detail'].'|'.$item['link'])])));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&isset($_POST['notification_action'])){try{verifyToken();if(!can('notifications','view'))throw new RuntimeException('Այս գործողությունը թույլատրված չէ։');$noticeKey=(string)($_POST['notification_key']??'');if(!preg_match('/^[a-f0-9]{40}$/',$noticeKey))throw new RuntimeException('Ծանուցման հղումը սխալ է։');$known=false;foreach($notifications as $item)if(hash_equals($noticeKey,sha1($item['title'].'|'.$item['detail'].'|'.$item['link']))){$known=true;break;}if(!$known)throw new RuntimeException('Ծանուցումն այլևս ակտիվ չէ։');$mark=db()->prepare('INSERT INTO user_notification_reads(user_id,notice_key,read_at) VALUES(?,?,NOW()) ON DUPLICATE KEY UPDATE read_at=VALUES(read_at)');$mark->execute([$notificationUserId,$noticeKey]);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>true,'key'=>$noticeKey],JSON_THROW_ON_ERROR);exit;}catch(Throwable $e){http_response_code($e instanceof RuntimeException?422:500);header('Content-Type: application/json; charset=utf-8');echo json_encode(['ok'=>false,'message'=>$e instanceof RuntimeException?$e->getMessage():'Ծանուցումը չհաջողվեց նշել որպես կարդացված։'],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}}
if($page==='requests'&&($_GET['ajax']??'')==='request_stats'){
 if(!can('requests','create')){http_response_code(403);exit;}
 $branch=currentLocation()?: (int)($_GET['branch_id']??0);
 if(!$branch||!activeLocation($branch)){http_response_code(422);exit;}
 $q=db()->prepare('SELECT p.id,p.optimal_qty,COALESCE(SUM(CASE WHEN s.expires_on IS NULL OR s.expires_on>=CURDATE() THEN s.qty ELSE 0 END),0) current_qty FROM products p LEFT JOIN stock_lots s ON s.product_id=p.id AND s.location_id=? WHERE p.active=1 GROUP BY p.id');$q->execute([$branch]);$stats=[];foreach($q->fetchAll() as $row)$stats[(int)$row['id']]=['current'=>(float)$row['current_qty'],'suggested'=>max(0,(float)$row['optimal_qty']-(float)$row['current_qty']),'average'=>0.0];
 $q=db()->prepare("SELECT product_id,SUM(qty)/3 average FROM movements WHERE type='consumption' AND reason='Ներքին օգտագործում' AND from_location=? AND happened_at>=DATE_SUB(CURDATE(),INTERVAL 90 DAY) GROUP BY product_id");$q->execute([$branch]);foreach($q->fetchAll() as $row)if(isset($stats[(int)$row['product_id']]))$stats[(int)$row['product_id']]['average']=(float)$row['average'];
 header('Content-Type: application/json; charset=utf-8');echo json_encode(['branch'=>$branch,'items'=>$stats],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;
}
if(($_GET['ajax']??'')==='notifications'){
 header('Content-Type: application/json; charset=utf-8');
 $liveItems=array_map(static function(array $item)use($notificationReadKeys):array{$key=sha1($item['title'].'|'.$item['detail'].'|'.$item['link']);return $item+['key'=>$key,'read'=>isset($notificationReadKeys[$key])];},array_slice($notifications,0,12));
 echo json_encode(['count'=>$notificationCount,'items'=>$liveItems],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
 exit;
}

function pill(string $status):string{$labels=['draft'=>'Սևագիր','sent'=>'Ուղարկված','review'=>'Ստուգման փուլում','approved'=>'Հաստատված','partially_approved'=>'Մասնակի հաստատված','collecting'=>'Հավաքագրվում է','ready_to_ship'=>'Պատրաստ է առաքման','cancelled'=>'Չեղարկված','rejected'=>'Մերժված','shipped'=>'Ուղարկված մասնաճյուղ','received'=>'Ստացված','closed'=>'Փակված','open'=>'Բաց','counted'=>'Հաստատման սպասող','pending'=>'Սպասում է','stock_shortage'=>'Սպասում է պաշարի համալրման','completed'=>'Կատարված','posted'=>'Գրանցված','active'=>'Ակտիվ'];$tone=['rejected'=>'red','open'=>'amber','counted'=>'violet','pending'=>'amber','stock_shortage'=>'amber','sent'=>'blue','review'=>'blue','shipped'=>'violet','received'=>'green','approved'=>'green','partially_approved'=>'amber','collecting'=>'blue','ready_to_ship'=>'violet','cancelled'=>'gray','closed'=>'green','completed'=>'green','posted'=>'green','active'=>'green'];return '<span class="badge '.($tone[$status]??'gray').'">'.h($labels[$status]??$status).'</span>';}
function pageHeading(string $title,string $sub=''):void{global $page,$modules;$section=$modules[$page][0]??$title;echo '<div class="page-heading"><div class="page-heading-copy"><h1>'.h($title).'</h1>'.($sub?'<p class="muted">'.h($sub).'</p>':'').'</div><nav class="page-breadcrumb" aria-label="Տեղորոշում"><span>Պահեստային համակարգ</span><span class="page-breadcrumb-separator" aria-hidden="true">/</span><b>'.h($section).'</b></nav></div>';}
function tableStart(array $cols):void{echo '<div class="page-card table-card"><div class="table-scroll"><table><thead><tr>';foreach($cols as $c)echo '<th>'.h($c).'</th>';echo '</tr></thead><tbody>';}
function tableEnd():void{echo '</tbody></table></div></div>';}
function trEmpty(int $n,string $text='Տվյալներ չկան։'):void{echo '<tr><td colspan="'.$n.'" class="empty-state">'.h($text).'</td></tr>';}
function newButton(string $text,string $kind,string $page):void{$module=match($kind){'supplier'=>'suppliers','branch'=>'branches','product'=>'products','user'=>'users',default=>$kind};if(can($module,'create'))echo '<button class="primary-button create-button" type="button" onclick="openModal(\''.h($page).'-modal\')"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg><span>'.h($text).'</span></button>';}
