idden':''?>><?=$notificationCount?></span></button><section id="notification-popover" class="notification-popover" aria-label="Ծանուցումներ" hidden><div class="notification-popover-head"><div><strong>Ծանուցումներ</strong><small id="notification-subtitle"><?=$notificationCount?> ակտիվ ազդանշան</small></div><a href="?page=notifications">Դիտել բոլորը <span aria-hidden="true">→</span></a></div><div id="notification-items" class="notification-items"><?php if(!$notifications):?><div class="notification-empty"><span class="notification-empty-icon">✓</span><strong>Ամեն ինչ կարգին է</strong><small>Նոր ծանուցումներ չկան։</small></div><?php else:foreach(array_slice($notifications,0,12) as $notice):?><a class="notification-item <?=isset($notificationReadKeys[sha1($notice['title'].'|'.$notice['detail'].'|'.$notice['link'])])?'is-read':''?>" data-notice-key="<?=h(sha1($notice['title'].'|'.$notice['detail'].'|'.$notice['link']))?>" href="<?=h($notice['link'])?>"><span class="notification-tone <?=h($notice['tone'])?>"></span><span class="notification-item-copy"><strong><?=h($notice['title'])?></strong><small><?=h($notice['detail'])?></small></span><span class="notification-chevron" aria-hidden="true">›</span></a><?php endforeach;endif?></div><div id="notification-live-status" class="notification-live-status" aria-live="polite"></div></section></div><button id="notification-sound" class="header-icon-button sound-toggle" type="button" aria-label="Միացնել ծանուցումների ձայնը" title="Միացնել ծանուցումների ձայնը"><svg class="sound-off" viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5ZM16 9l5 6m0-6-5 6"/></svg><svg class="sound-on" viewBox="0 0 24 24" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4V5ZM15.5 8.5a5 5 0 0 1 0 7m3-10a9 9 0 0 1 0 13"/></svg></button><?php endif?><div class="profile-menu"><button id="profile-toggle" class="profile-trigger" type="button" aria-label="Անձնական տվյալներ" aria-expanded="false" aria-controls="profile-popover"><span class="profile