<?php if($page==='dashboard'):
 pageHeading('Բարի գալուստ համակարգ','Կազմակերպության պահեստային պաշարների ամփոփ պատկերը');
 $answerProductId=filter_var($_GET['answer_product']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:0;$answerFrom=(string)($_GET['answer_from']??date('Y-m-01'));$answerTo=(string)($_GET['answer_to']??date('Y-m-d'));if(!validDate($answerFrom))$answerFrom=date('Y-m-01');if(!validDate($answerTo)||$answerTo<$answerFrom)$answerTo=date('Y-m-d');$answerProduct=null;$answerLots=[];$answerLocations=[];$answerActivity=[];$canSeeAnswerCosts=$canSeeCostData;
 if($answerProductId){$answerQuery=db()->prepare('SELECT id,code,name,unit,supplier_id,purchase_price FROM products WHERE id=? AND active=1');$answerQuery->execute([$answerProductId]);$answerProduct=$answerQuery->fetch();if(!$answerProduct)$answerProductId=0;}
 if($answerProduct){$lotQuery='SELECT sl.lot_no,sl.expires_on,sl.received_on,sl.location_id,sl.supplier_id,sl.unit_cost,sl.bin_location,sl.qty,b.name location_name,COALESCE(s.name,ps.name) supplier_name FROM stock_lots sl LEFT JOIN branches b ON b.id=sl.location_id LEFT JOIN suppliers s ON s.id=sl.supplier_id JOIN products p ON p.id=sl.product_id LEFT JOIN suppliers ps ON ps.id=p.supplier_id WHERE sl.product_id=? AND sl.qty>0'.($location?' AND sl.location_id=?':'').' ORDER BY (sl.expires_on IS NULL),sl.expires_on,sl.received_on,sl.id';$lotQueryStmt=db()->prepare($lotQuery);$lotQueryStmt->execute($location?[$answerProductId,$location]:[$answerProductId]);$answerLots=$lotQueryStmt->fetchAll();$locationQuery=$location?"SELECT b.id,b.name,COALESCE(SUM(sl.qty),0) qty FROM branches b LEFT JOIN stock_lots sl ON sl.location_id=b.id AND sl.product_id=? WHERE b.active=1 AND b.id=? GROUP BY b.id":"SELECT 0 id,'Կենտրոնական պահեստ' name,COALESCE(SUM(qty),0) qty FROM stock_lots WHERE product_id=? AND location_id=0 UNION ALL SELECT b.id,b.name,COALESCE(SUM(sl.qty),0) qty FROM branches b LEFT JOIN stock_lots sl ON sl.location_id=b.id AND sl.product_id=? WHERE b.active=1 AND b.code<>'CENTRAL' GROUP BY b.id ORDER BY id";$locationStmt=db()->prepare($locationQuery);$locationStmt->execute($location?[$answerProductId,$location]:[$answerProductId,$answerProductId]);$answerLocations=$locationStmt->fetchAll();$activitySql='SELECT branch_id,SUM(requested_qty) requested_qty,SUM(approved_qty) approved_qty FROM stock_requests r JOIN request_items ri ON ri.request_id=r.id WHERE ri.product_id=? AND r.status<>\'draft\' AND DATE(r.created_at) BETWEEN ? AND ?'.($location?' AND r.branch_id=?':'').' GROUP BY branch_id';$activityStmt=db()->prepare($activitySql);$activityStmt->execute($location?[$answerProductId,$answerFrom,$answerTo,$location]:[$answerProductId,$answerFrom,$answerTo]);foreach($activityStmt->fetchAll() as $activity)$answerActivity[(int)$activity['branch_id']]=['requested'=>(float)$activity['requested_qty'],'approved'=>(float)$activity['approved_qty'],'received'=>0.0,'used'=>0.0];$movementSql=$location?"SELECT ? location_id,SUM(CASE WHEN type IN ('branch_in','branch_transfer') THEN qty ELSE 0 END) received_qty,SUM(CASE WHEN type='consumption' THEN qty ELSE 0 END) used_qty FROM movements WHERE product_id=? AND DATE(happened_at) BETWEEN ? AND ? AND ((type IN ('branch_in','branch_transfer') AND to_location=?) OR (type='consumption' AND from_location=?))":"SELECT COALESCE(to_location,from_location,0) location_id,SUM(CASE WHEN type IN ('branch_in','branch_transfer') THEN qty ELSE 0 END) received_qty,SUM(CASE WHEN type='consumption' THEN qty ELSE 0 END) used_qty FROM movements WHERE product_id=? AND DATE(happened_at) BETWEEN ? AND ? AND (type IN ('branch_in','branch_transfer') OR type='consumption') GROUP BY COALESCE(to_location,from_location,0)";$movementStmt=db()->prepare($movementSql);$movementStmt->execute($location?[$location,$answerProductId,$answerFrom,$answerTo,$location,$location]:[$answerProductId,$answerFrom,$answerTo]);foreach($movementStmt->fetchAll() as $activity){$branchId=(int)$activity['location_id'];$answerActivity[$branchId]??=['requested'=>0.0,'approved'=>0.0,'received'=>0.0,'used'=>0.0];$answerActivity[$branchId]['received']=(float)$activity['received_qty'];$answerActivity[$branchId]['used']=(float)$activity['used_qty'];}ksort($answerActivity);}
 ?><article class="page-card management-answer-card"><div class="card-heading"><div><h2>Ապրանքի ամբողջական պատկերը</h2><p>Մնացորդ, պահեստավորման վայր, LOT, ժամկետ, մատակարար և պահանջարկ՝ մեկ որոնմամբ</p></div><a class="text-link" href="?page=stock">Բացել ընդհանուր մնացորդը →</a></div><form class="form-grid management-answer-filters" method="get"><input type="hidden" name="page" value="dashboard"><label>Ապրանք<select name="answer_product"><option value="">Ընտրել ապրանքը</option><?php foreach($products as $productOption):?><option value="<?=h($productOption['id'])?>" <?=((int)$productOption['id']===$answerProductId)?'selected':''?>><?=h($productOption['code'].' · '.$productOption['name'])?></option><?php endforeach?></select></label><label>Սկսած<input type="date" name="answer_from" value="<?=h($answerFrom)?>"></label><label>Մինչև<input type="date" name="answer_to" value="<?=h($answerTo)?>"></label><div class="form-actions"><button class="primary-button">Ցույց տալ ամփոփումը</button></div></form><?php if($answerProduct):$answerTotal=array_sum(array_map(static fn($row)=>(float)$row['qty'],$answerLocations));$answerExpired=array_sum(array_map(static fn($row)=>$row['expires_on']!==null&&$row['expires_on']<date('Y-m-d')?(float)$row['qty']:0,$answerLots));?><div class="management-answer-summary"><article><small>Ընդհանուր մնացորդ</small><strong><?=num($answerTotal)?> <?=h($answerProduct['unit'])?></strong></article><?php if($canSeeAnswerCosts):?><article><small>Ընթացիկ արժեք</small><strong><?=num(array_sum(array_map(static fn($row)=>(float)$row['qty']*(float)$row['unit_cost'],$answerLots)))?> ֏</strong></article><?php endif?><article><small>Ժամկետանց մնացորդ</small><strong><?=num($answerExpired)?> <?=h($answerProduct['unit'])?></strong></article><article><small>Հաշվետվության շրջան</small><strong><?=h(date('d.m.Y',strtotime($answerFrom)))?> – <?=h(date('d.m.Y',strtotime($answerTo)))?></strong></article></div><div class="management-answer-columns"><section><h3>Որտեղ է և որ LOT-