<?php elseif($page==='requests'):
 pageHeading('Մասնաճյուղերի պահանջագրեր','Պահանջ, հաստատում, FEFO հավաքագրում և ստացման հաստատում');newButton('Նոր պահանջագիր','requests','requests');tableStart(['Պահանջագիր','Ամսաթիվ','Մասնաճյուղ','Հայցող / կատարողներ','Ապրանքներ','Հրատապություն','Կարգավիճակ','Գործողություն']);$sql='SELECT r.*,b.name branch_name,u.name actor_name,sender.name sender_name,receiver.name receiver_name,(SELECT COUNT(*) FROM request_items i WHERE i.request_id=r.id) line_count FROM stock_requests r JOIN branches b ON b.id=r.branch_id JOIN users u ON u.id=r.requested_by LEFT JOIN users sender ON sender.id=r.sent_by LEFT JOIN users receiver ON receiver.id=r.received_by';if(currentLocation())$sql.=' WHERE r.branch_id='.currentLocation();if(isset($_GET['status'])&&in_array((string)$_GET['status'],['draft','sent','review','approved','partially_approved','collecting','ready_to_ship','shipped','received','closed','rejected','cancelled'],true))$sql.=(currentLocation()?' AND':' WHERE').' r.status=\''.addslashes((string)$_GET['status']).'\'';$sql.=' ORDER BY r.id DESC';$rows=db()->query($sql)->fetchAll();if(!$rows)trEmpty(8);foreach($rows as $r):?><tr><td><b><?=h($r['request_no'])?></b><?php if(in_array($r['status'],['shipped','received','closed'],true)):?><a class="dispatch-link" href="?page=dispatch&amp;id=<?=$r['id']?>">Դիտել / տպել բաշխումը →</a><?php endif?><small><?=h($r['reason'])?></small></td><td><?=h(date('d.m.Y',strtotime($r['created_at'])))?></td><td><?=h($r['branch_name'])?></td><td><?=h($r['actor_name'])?><small>Ուղարկել է՝ <?=h($r['sender_name']??'—')?> · Ստացել է՝ <?=h($r['receiver_name']??'—')?></small></td><td><?=h($r['line_count'])?> ապրանք</td><td><?=h(['urgent'=>'Շտապ','high'=>'Բարձր','normal'=>'Սովորական'][$r['urgency']]??$r['urgency'])?></td><td><?=pill($r['status'])?><?php if($r['status']==='rejected'):?><small><?=h($r['rejection_reason'])?></small><?php endif?></td><td class="actions-cell"><?php if(in_array($r['status'],['sent','review'],true)&&can('requests','approve')):?><button class="table-action" onclick="openModal('review-<?=$r['id']?>')">Դիտել / որոշել</button><?php elseif(in_array($r['status'],['approved','partially_approved'],true)&&can('requests','edit')&&currentLocation()===0):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_collect">Սկսել հավաքագրումը</button></form><?php elseif($r['status']==='collecting'&&can('requests','edit')&&currentLocation()===0):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_ready">Պատրաստ է առաքման</button></form><?php elseif($r['status']==='ready_to_ship'&&can('requests','edit')&&currentLocation()===0):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_ship">Ուղարկել մասնաճյուղ</button></form><?php elseif($r['status']==='draft'&&can('requests','edit')&&(isAdminUser()||(int)$r['branch_id']===currentLocation())&&(isAdminUser()||(int)$r['requested_by']===(int)$u['id'])):?><button class="table-action" onclick="openModal('edit-request-<?=$r['id']?>')">Շարունակել սևագիրը</button><form method="post" data-confirm="cancel-request"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action danger-link" name="action" value="request_cancel">Չեղարկել</button></form><?php elseif(in_array($r['status'],['draft','sent','review'],true)&&can('requests','edit')&&(isAdminUser()||(int)$r['branch_id']===currentLocation())):?><form method="post" data-confirm="cancel-request"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action danger-link" name="action" value="request_cancel">Չեղարկել</button></form><?php elseif($r['status']==='received'&&can('requests','edit')&&(currentLocation()||isAdminUser())):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_close">Փակել պահանջագիրը</button></form><?php elseif($r['status']==='shipped'&&can('requests','edit')&&(currentLocation()||isAdminUser())):?><form method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="table-action" name="action" value="request_receive"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>Ստացա</button></form><?php else:?>—<?php endif?></td></tr><?php endforeach;tableEnd();foreach($rows as $r)if($r['status']==='draft'&&(isAdminUser()||(int)$r['branch_id']===currentLocation())&&(isAdminUser()||(int)$r['requested_by']===(int)$u['id']))renderRequestEditModal($r,$products);
