$reportFrom=(string)($_GET['from']??date('Y-m-01'));$reportTo=(string)($_GET['to']??date('Y-m-d'));if(!validDate($reportFrom))$reportFrom=date('Y-m-01');if(!validDate($reportTo))$reportTo=date('Y-m-d');if($reportFrom>$reportTo){[$reportFrom,$reportTo]=[$reportTo,$reportFrom];}$reportBranch=(string)($_GET['branch_id']??'');if(currentLocation())$reportBranch=(string)currentLocation();elseif($reportBranch!==''&&!ctype_digit($reportBranch))$reportBranch='';$expenseSql="SELECT b.name branch_name,p.code,p.name product_name,p.unit,SUM(m.qty) used_qty,CASE WHEN SUM(m.qty)>0 THEN SUM(m.qty*m.unit_cost)/SUM(m.qty) ELSE 0 END average_unit_cost,SUM(m.qty*m.unit_cost) used_cost FROM movements m JOIN products p ON p.id=m.product_id JOIN branches b ON b.id=m.from_location WHERE m.type='consumption' AND m.reason='Ներքին օգտագործում' AND m.happened_at>=? AND m.happened_at<DATE_ADD(?,INTERVAL 1 DAY)";$expenseParams=[$reportFrom,$reportTo];if($reportBranch!==''){$expenseSql.=' AND m.from_location=?';$expenseParams[]=(int)$reportBranch;}$expenseSql.=' GROUP BY b.id,p.id ORDER BY b.name,p.name';$expenseQuery=db()->prepare($expenseSql);$expenseQuery->execute($expenseParams);$expenseRows=$expenseQuery->fetchAll();$showExpenseCost=can('purchases','view');if(($_GET['export']??'')==='branch_expense'){$headers=['Մասնաճյուղ','Կոդ','Ապրանք','Միավոր','Օգտագործված քանակ'];if($showExpenseCost)array_push($headers,'Միջին միավորի արժեք','Ընդհանուր արժեք');$csvRows=[];foreach($expenseRows as $row){$csvRow=[$row['branch_name'],$row['code'],$row['product_name'],$row['unit'],$row['used_qty']];if($showExpenseCost)array_push($csvRow,$row['average_unit_cost'],$row['used_cost']);$csvRows[]=$csvRow;}downloadExport('diagen-branch-expense.csv',$headers,$csvRows);}
