ocation()?" AND m.from_location=".currentLocation():"")." GROUP BY b.id,p.id ORDER BY b.name,p.name";$averageRows=db()->query($averageSql)->fetchAll();if(($_GET['export']??'')==='average_usage'){$averageHeaders=['Մասնաճյուղ','Կոդ','Ապրանք','90 օրվա օգտագործում','Միջին ամսական'];$averageExportRows=[];foreach($averageRows as $averageRow)$averageExportRows[]=[$averageRow['branch_name'],$averageRow['code'],$averageRow['product_name'],$averageRow['consumed'],$averageRow['monthly_average']];downloadExport('diagen-average-monthly-usage.csv',$averageHeaders,$averageExportRows);}?><article id="average-usage" class="page-card report-usage-card"><div class="card-heading"><div><h2>Միջին ամսական սպառում</h2><p>Հաշվարկված վերջին 90 օրվա օգտագործման շարժերից</p></div><div class="report-export-actions"><a class="secondary-button" href="?page=reports&amp;export=average_usage">Ներբեռնել CSV</a><a class="secondary-button" href="?page=reports&amp;export=average_usage&amp;format=xlsx">Ներբեռնել Excel</a></div></div><?php tableStart(['Մասնաճյուղ','Կոդ','Ապրանք','90 օրվա օգտագործում','Միջին ամսական']);if(!$averageRows)trEmpty(5,'Վերջին 90 օրում օգտագործման գրառում չկա։');foreach($averageRows as $average):?><tr><td><?=h($average['branch_name'])?></td><td><?=h($average['code'])?></td><td><?=h($average['product_name'])?></td><td><?=num($average['consumed'])?></td><td><b><?=num($average['monthly_average'])?></b></td></tr><?php endforeach;tableEnd();?></article><?php elseif($page==='roles'):
