['purchase_price'])?>"></label><label>Պահման պայմաններ<input name="storage_conditions" value="<?=h($r['storage_conditions'])?>"></label><label class="check-label"><input type="checkbox" name="refrigerated" <?=!empty($r['refrigerated'])?'checked':''?>> Սառնարանային պահպանում</label><label class="check-label"><input type="checkbox" name="lot_control" <?=!empty($r['lot_control'])?'checked':''?>> LOT վերահսկում</label><label class="check-label"><input type="checkbox" name="expiry_control" <?=!empty($r['expiry_control'])?'checked':''?>> Պիտանելիության ժամկետ</label><label class="check-label"><input type="checkbox" name="active" <?=!empty($r['active'])?'checked':''?>> Ակտիվ ապրանք</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('<?=h($id)?>')">Չեղարկել</button><button class="primary-button">Պահպանել քարտը</button></div></form></div><?php }
function renderUserModal(array $roles,array $branches):void{?><div id="users-modal" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="user"><input type="hidden" name="return_page" value="users"><div class="modal-head"><div><h2>Ստեղծել օգտատիրոջ հաշիվ</h2><p>Ընտրեք դերը և կցված մասնաճյուղը</p></div><button type="button" class="icon-button" onclick="closeModal('users-modal')">×</button></div><div class="form-grid"><label>Անուն<input name="name" required></label><label>Էլ. փոստ<input name="email" type="email" required></label><label>Դեր<select name="role_id" required><?=optionRows($roles)?></select></label><label>Մասնաճյուղ<select name="branch_id"><option value="">Կենտրոնական / ընդհանուր</option><?=optionRows($branches)?></select></label><label>Գաղտնաբառ<input name="password" type="password" minlength="8" required></label><label class="check-label"><input type="checkbox" name="active" checked> Ակտիվ հաշիվ</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('users-modal')">Չեղարկել</button><button class="primary-button">Ստեղծել</button></div></form></div><?php }
function renderUserEditModal(array $roles,array $branches,array $r):void{$id='edit-users-'.$r['id'];?><div id="<?=h($id)?>" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="user"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="return_page" value="users"><div class="modal-head"><div><h2>Փոփոխել օգտատիրոջ տվյալները</h2><p>Դատարկ գաղտնաբառի դեպքում գործողը չի փոխվի</p></div><button type="button" class="icon-button" onclick="closeModal('<?=h($id)?>')">×</button></div><div class="form-grid"><label>Անուն<input name="name" value="<?=h($r['name'])?>" required></label><label>Էլ. փոստ<input name="email" type="email" value="<?=h($r['email'])?>" required></label><label>Դեր<select name="role_id" required><?=optionRows($roles,$r['role_id'])?></select></label><label>Մասնաճյուղ<select name="branch_id"><option value="">Կենտրոնական / ընդհանուր</option><?=optionRows($branches,$r['branch_id'])?></select></label><label>Նոր գաղտնաբառ<input name="password" type="password" minlength="8"></label><label class="check-label"><input type="checkbox" name="active" <?=!empty($r['active'])?'checked':''?>> Ակտիվ հաշիվ</label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('<?=h($id)?>')">Չեղարկել</button><button class="primary-button">Պահպանել</button></div></form></div><?php }
function renderPurchaseModal(array $suppliers,array $products):void{$productOptions='<option value="">Ընտրել ապրանքը</option>';foreach($products as $product)$productOptions.='<option value="'.(int)$product['id'].'" data-price="'.h((string)($product['purchase_price']??0)).'">'.h($product['code'].' · '.$product['name']).'</option>';?><div id="purchases-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="purchase_create"><input type="hidden" name="return_page" value="purchases"><div class="modal-head"><div><h2>Կազմել գնման պատվեր</h2><p>Մեկ պատվերում կարող եք ավելացնել մի քանի ապրանք, քանակ և առանձին գին</p></div><button type="button" class="icon-button" onclick="closeModal('purchases-modal')">×</button></div><div class="form-grid"><label class="span-2">Մատակարար<select name="supplier_id" required><?=optionRows($suppliers)?></select></label><div class="span-2 purchase-items-heading"><strong>Պատվերի ապրանքները</strong><button type="button" class="secondary-button" data-add-purchase-item>＋ Ավելացնել ապրանք</button></div><div class="span-2 purchase-item-lines" data-purchase-items><div class="purchase-item-row"><label>Ապրանք<select name="items[0][product_id]" required><?=$productOptions?></select></label><label>Քանակ<input name="items[0][qty]" type="number" min="0.001" step="0.001" required></label><label>Միավորի գին, դրամ<input name="items[0][unit_cost]" type="number" min="0" step="0.01" required></label><button type="button" class="icon-button purchase-item-remove" data-remove-purchase-item aria-label="Հեռացնել ապրանքը" disabled>×</button></div></div><template id="purchase-item-template"><div class="purchase-item-row"><label>Ապրանք<select name="items[__INDEX__][product_id]" required><?=$productOptions?></select></label><label>Քանակ<input name="items[__INDEX__][qty]" type="number" min="0.001" step="0.001" required></label><label>Միավորի գին, դրամ<input name="items[__INDEX__][unit_cost]" type="number" min="0" step="0.01" required></label><button type="button" class="icon-button purchase-item-remove" data-remove-purchase-item aria-label="Հեռացնել ապրանքը">×</button></div></template><label>Պատվերի ամսաթիվ<input name="ordered_on" type="date" value="<?=date('Y-m-d')?>" required></label><label>Սպասվող առաքում<input name="expected_on" type="date"></label><label class="span-2">Նշում<textarea name="note"></textarea></label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('purchases-modal')">Չեղարկել</button><button class="primary-button">Ուղարկել հաստատման</button></div></form></div><?php }
function renderReceiptModal(array $orders,int $selected):void{?>
<div id="receipts-modal" class="modal-backdrop" hidden><form class="modal-card wide-modal" method="post"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="receipt_create"><input type="hidden" name="return_page" value="receipts"><div class="modal-head"><div><h2>Գրանցել պատվերի մուտքը</h2><p>Մեկ հաստատված պատվերի մի քանի ապրանք գրանցեք մեկ փաստաթղթով։</p></div><button type="button" class="icon-button" onclick="closeModal('receipts-modal')">×</button></div><div class="form-grid"><label>Մուտքի ամսաթիվ<input type="date" name="received_on" value="<?=date('Y-m-d')?>" required></label><label>Հաշիվ-ապրանքագրի համար<input name="invoice_no" maxlength="100"></label><label>Պայմանագրի համար<input name="contract_no" maxlength="100" placeholder="Լռելյայն՝ մատակարարի գործող պայմանագիրը"></label><label>Նշում<input name="note" maxlength="500"></label></div><div id="receipt-lines" class="receipt-lines"><div class="receipt-line"><label>Հաստատված պատվերի ապրանք<select name="items[0][purchase_order_item_id]" required><option value="">Ընտրել պատվերի տողը</option><?php foreach($orders as $order):?><option value="<?=h($order['id'])?>" data-order="<?=h($order['order_id'])?>" <?=$selected===(int)$order['id']?'selected':''?>><?=h($order['label'])?></option><?php endforeach?></select></label><label>Ստացված քանակ<input type="number" min="0.001" step="0.001" name="items[0][qty]" required></label><label>LOT / սերիա<input name="items[0][lot_no]" maxlength="100" required></label><label>Պիտանի է մինչև<input type="date" name="items[0][expires_on]"></label><label>Պահեստային տեղ<input name="items[0][bin_location]" maxlength="100" placeholder="Օր.՝ A-01-01"></label></div></div><button type="button" class="text-link" id="receipt-add-line">＋ Ավելացնել ապրանք</button><p class="form-hint">Մեկ փաստաթղթում հնարավոր է միավորել միայն նույն գնման պատվերի տողերը։</p><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('receipts-modal')">Չեղարկել</button><button class="primary-button" <?=empty($orders)?'disabled':''?>>Գրանցել մուտքի փաստաթուղթը</button></div></form></div><?php }function renderConsumeModal(array $products,array $branches):void{?><div id="consume-modal" class="modal-backdrop" hidden><form method="post" class="modal-card"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="consume"><input type="hidden" name="return_page" value="stock"><div class="modal-head"><div><h2>Գրանցել ներքին օգտագործումը</h2><p>Ապրանքը դուրս է գրվում ամենավաղ պիտանելիությամբ LOT-ից</p></div><button class="icon-button" type="button" onclick="closeModal('consume-modal')">×</button></div><div class="form-grid"><label>Պահեստ<select name="location_id" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,currentLocation())?></select><?php if(currentLocation()):?><input type="hidden" name="location_id" value="<?=currentLocation()?>"><?php endif?></label><label>Ապրանք<select name="product_id" required><?=productOptions($products)?></select></label><label>Ելքի պատճառ<select name="issue_type"><option value="usage">Ներքին օգտագործում</option><option value="expired">Ժամկետանցի դուրսգրում</option><option value="damaged">Վնասված ապրանքի դուրսգրում</option><option value="other">Այլ պատճառ</option></select></label><label>Պատճառի բացատրություն<input name="reason_note" placeholder="Պարտադիր է «Այլ պատճառ» ընտրելիս"></label><label>Ելքի քանակ<input type="number" min="0.001" step="0.001" name="qty" required></label></div><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('consume-modal')">Չեղարկել</button><button class="primary-button">Գրանցել ելքը</button></div></form></div><?php }
function renderStockAdjustmentModal(array $products,array $branches):void{$lotsSql='SELECT s.id,s.location_id,s.product_id,s.lot_no,s.expires_on,s.qty,p.code,p.name product_name,b.name branch_name FROM stock_lots s JOIN products p ON p.id=s.product_id LEFT JOIN branches b ON b.id=s.location_id WHERE s.qty>0';if(currentLocation())$lotsSql.=' AND s.location_id='.currentLocation();$lotsSql.=' ORDER BY p.name,(s.expires_on IS NULL),s.expires_on,s.lot_no';$lots=db()->query($lotsSql)->fetchAll();?><div id="stock-adjust-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="stock_adjust"><input type="hidden" name="return_page" value="stock"><div class="modal-head"><div><h2>Ուղղել պահեստի մնացորդը</h2><p>Յուրաքանչյուր ուղղում կգրանցվի շարժերի և գործողությունների պատմության մեջ</p></div><button class="icon-button" type="button" onclick="closeModal('stock-adjust-modal')">×</button></div><div class="form-grid"><label>Պահեստ<select id="stock-adjust-location" name="location_id" <?=currentLocation()?'disabled':''?>><option value="0" <?=!currentLocation()?'selected':''?>>Կենտրոնական պահեստ</option><?=optionRows($branches,currentLocation())?></select><?php if(currentLocation()):?><input type="hidden" name="location_id" value="<?=currentLocation()?>"><?php endif?></label><label>Ապրանք<select id="stock-adjust-product" name="product_id" required><?=productOptions($products)?></select></label><label class="span-2">Գոյություն ունեցող LOT<select id="stock-adjust-lot" name="lot_id"><option value="0">Նոր խմբաքանակ եմ ավելացնում</option><?php foreach($lots as $lot):?><option value="<?=$lot['id']?>" data-location="<?=$lot['location_id']?>" data-product="<?=$lot['product_id']?>"><?=h($lot['code'].' · '.$lot['product_name'].' · '.$lot['lot_no'].' · '.($lot['branch_name']??'Կենտրոնական պահեստ').' · մնացորդ '.num($lot['qty']).($lot['expires_on']?' · մինչև '.date('d.m.Y',strtotime($lot['expires_on'])):''))?></option><?php endforeach?></select><small>Առկա LOT ընտրեք թե՛ նվազեցման, թե՛ ավելացման համար։</small></label><label>Քանակի փոփոխություն<input name="delta_qty" type="number" step="0.001" required placeholder="Օրինակ՝ 5 կամ -2"><small>Դրական թիվը ավելացնում է, բացասականը՝ նվազեցնում։</small></label><label>Ճշգրտման պատճառ<input name="reason" required maxlength="255" placeholder="Օրինակ՝ վերահաշվարկի արդյունք"></label><label>Նոր LOT-ի կոդ<input name="lot_no" placeholder="Պարտադիր է նոր LOT-ի դեպքում"></label><label>Նոր LOT-ի ժամկետ<input name="expires_on" type="date"></label><label>Միավորի արժեք, դրամ<input name="unit_cost" type="number" min="0" step="0.01" value="0"></label><label>Պահեստային տեղ<input name="bin_location" placeholder="Օր.՝ A-01-02"></label></div><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('stock-adjust-modal')">Չեղարկել</button><button class="primary-button">Պահպանել ուղղումը</button></div></form></div><?php }
function renderRequestModal(array $products,array $branches,int $branch):void{?><div id="requests-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="request_create"><input type="hidden" name="return_page" value="requests"><div class="modal-head"><div><h2>Նոր մասնաճյուղային պահանջագիր</h2><p>Ընթացիկ մնացորդը և առաջարկվող քանակը երևում են ընտրված ապրանքի մոտ</p></div><button class="icon-button" type="button" onclick="closeModal('requests-modal')">×</button></div><div class="form-grid"><label>Մասնաճյուղ<select name="branch_id" <?=currentLocation()?'disabled':''?> required><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="branch_id" value="<?=$branch?>"><?php endif?></label><label>Հրատապություն<select name="urgency"><option value="normal">Սովորական</option><option value="high">Բարձր</option><option value="urgent">Շտապ</option></select></label><label class="span-2">Հիմնավորում<textarea name="reason" placeholder="Պահանջի նպատակը"></textarea></label></div><div id="request-lines"><div class="request-line"><label>Ապրանք<select name="items[0][product_id]" required><option value="">Ընտրել ապրանքը</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Պահանջվող քանակ<input name="items[0][qty]" type="number" min="0.001" step="0.001" required></label><label>Մեկնաբանություն<input name="items[0][note]"></label></div></div><button type="button" class="text-link" onclick="addRequestLine()">＋ Ավելացնել ապրանք</button><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('requests-modal')">Չեղարկել</button><button class="secondary-button" name="submit_mode" value="draft">Պահպանել սևագիր</button><button class="primary-button" name="submit_mode" value="send">Ուղարկել պահանջագիրը</button></div></form></div><?php }
function renderRequestEditModal(array $request,array $products):void{$q=db()->prepare('SELECT * FROM request_items WHERE request_id=? ORDER BY id');$q->execute([$request['id']]);$items=$q->fetchAll();?>
<div id="edit-request-<?=$request['id']?>" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="request_update_draft"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$request['id']?>"><div class="modal-head"><div><h2>Խմբագրել <?=h($request['request_no'])?></h2><p>Սևագիրը կարող եք պահպանել կամ ուղարկել ստուգման։</p></div><button class="icon-button" type="button" onclick="closeModal('edit-request-<?=$request['id']?>')">×</button></div><div class="form-grid"><label>Հրատապություն<select name="urgency"><option value="normal" <?=$request['urgency']==='normal'?'selected':''?>>Սովորական</option><option value="high" <?=$request['urgency']==='high'?'selected':''?>>Բարձր</option><option value="urgent" <?=$request['urgency']==='urgent'?'selected':''?>>Շտապ</option></select></label><label class="span-2">Հիմնավորում<textarea name="reason"><?=h($request['reason'])?></textarea></label></div><div id="request-lines"><?php foreach($items as $i=>$item):?><div class="request-line"><label>Ապրանք<select name="items[<?=$i?>][product_id]" required><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=$p['id']==$item['product_id']?'selected':''?>><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Պահանջվող քանակ<input name="items[<?=$i?>][qty]" type="number" min="0.001" step="0.001" value="<?=h($item['requested_qty'])?>" required></label><label>Մեկնաբանություն<input name="items[<?=$i?>][note]" value="<?=h($item['note'])?>"></label></div><?php endforeach?></div><button type="button" class="text-link" onclick="addRequestLine()">＋ Ավելացնել ապրանք</button><div class="modal-actions"><button class="secondary-button" name="submit_mode" value="draft">Պահպանել սևագիրը</button><button class="primary-button" name="submit_mode" value="send">Ուղարկել ստուգման</button></div></form></div><?php }
function renderReviewModal(array $r,array $products):void{
 $q=db()->prepare("SELECT i.*,p.name,p.code,p.unit,
  (SELECT COALESCE(SUM(qty),0) FROM stock_lots s WHERE s.product_id=p.id AND s.location_id=0 AND (s.expires_on IS NULL OR s.expires_on>=CURDATE())) central_qty,
  (SELECT COALESCE(SUM(ri2.approved_qty),0) FROM request_items ri2 JOIN stock_requests r2 ON r2.id=ri2.request_id WHERE ri2.product_id=p.id AND r2.status IN ('approved','partially_approved','collecting','ready_to_ship')) central_reserved,
  (SELECT COALESCE(SUM(qty),0) FROM stock_lots s WHERE s.product_id=p.id AND s.location_id=? AND (s.expires_on IS NULL OR s.expires_on>=CURDATE())) branch_qty,
  (SELECT COALESCE(SUM(m.qty)/3,0) FROM movements m WHERE m.product_id=p.id AND m.from_location=? AND m.type='consumption' AND m.reason='Ներքին օգտագործում' AND m.happened_at>=DATE_SUB(CURDATE(),INTERVAL 90 DAY)) monthly_usage
  FROM request_items i JOIN products p ON p.id=i.product_id WHERE i.request_id=?");
 $q->execute([$r['branch_id'],$r['branch_id'],$r['id']]);$items=$q->fetchAll();?>
 <div id="review-<?=$r['id']?>" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="request_review"><input type="hidden" name="return_page" value="requests"><input type="hidden" name="id" value="<?=$r['id']?>"><div class="modal-head"><div><h2>Ստուգել <?=h($r['request_no'])?></h2><p><?=h($r['branch_name']??'Մասնաճյուղ')?> · <?=h($r['reason'])?></p></div><button class="icon-button" type="button" onclick="closeModal('review-<?=$r['id']?>')">×</button></div>
 <?php foreach($items as $it):$free=max(0,(float)$it['central_qty']-(float)$it['central_reserved']);$suggested=min((float)$it['requested_qty'],$free);?><div class="review-line"><div><b><?=h($it['code'].' · '.$it['name'])?></b><small>Մասնաճյուղում՝ <?=num($it['branch_qty'])?> <?=h($it['unit'])?> · Միջին ամսական սպառում՝ <?=num($it['monthly_usage'])?> <?=h($it['unit'])?> · Կենտրոնի ազատ մնացորդ՝ <?=num($free)?></small></div><label>Պահանջված՝ <?=num($it['requested_qty'])?><input type="number" name="approved[<?=$it['id']?>]" min="0" max="<?=$suggested?>" step="0.001" value="<?=$suggested?>"></label></div><?php endforeach?><label>Մերժման պատճառ (մերժելիս պարտադիր)<textarea name="rejection_reason"></textarea></label><div class="modal-actions"><?php if($r['status']==='sent'):?><button class="secondary-button" name="decision" value="start_review">Վերցնել ստուգման փուլ</button><?php endif?><button class="danger-button" name="decision" value="reject">Մերժել</button><button class="primary-button" name="decision" value="approve">Հաստատել քանակները</button></div></form></div><?php }

function renderInventoryModal(array $r):void{
 $q=db()->prepare('SELECT il.*,p.name,p.code,p.unit,p.lot_control,p.expiry_control,s.lot_no FROM inventory_lines il JOIN products p ON p.id=il.product_id LEFT JOIN stock_lots s ON s.id=il.lot_id WHERE il.session_id=? ORDER BY p.name');$q->execute([$r['id']]);$lines=$q->fetchAll();$suppliers=db()->query('SELECT id,name FROM suppliers WHERE active=1 ORDER BY name')->fetchAll(PDO::FETCH_KEY_PAIR);?>
 <div id="count-<?=$r['id']?>" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="inventory_count"><input type="hidden" name="return_page" value="inventory"><input type="hidden" name="session_id" value="<?=$r['id']?>"><div class="modal-head"><div><h2><?=h($r['inventory_no'])?> · Փաստացի հաշվարկ</h2><p><?=count($lines)?'Հաշվարկված մնացորդը ֆիքսվել է գույքագրումն սկսելիս':'Այս գույքագրման մեկնարկին ապրանքային տողեր չեն գրանցվել'?></p></div><button class="icon-button" type="button" onclick="closeModal('count-<?=$r['id']?>')">×</button></div><div class="count-list"><?php if(!$lines):?><div class="inventory-empty-state"><span class="inventory-empty-icon" aria-hidden="true">!</span><div><b>Այս գույքագրումը դատարկ է</b><p>Սա ավելի վաղ ստեղծված գույքագրում է․ ներկայիս տվյալները հին հաշվարկի մեջ չենք ավելացնում։ Փակեք պատուհանը և սկսեք նոր գույքագրում։</p></div></div><?php else:foreach($lines as $line):$lineId=(int)$line['id'];?><div class="count-line"><div><b><?=h($line['name'])?></b><small><?=h($line['code'])?> · LOT <?=h($line['lot_no']??'—')?> · Հաշվառված՝ <?=num($line['expected_qty'])?> <?=h($line['unit'])?></small></div><label>Փաստացի քանակ<input name="counted[<?=$lineId?>]" type="number" min="0" step="0.001" value="<?=h($line['counted_qty']??'')?>" required></label><label>Տարբերության պատճառ<input name="reason[<?=$lineId?>]" value="<?=h($line['difference_reason'])?>" placeholder="Լրացնել տարբերության դեպքում"></label><?php if(!$line['lot_id']):?><div class="inventory-new-lot-fields"><strong>Նոր մնացորդի LOT-ի տվյալներ <small>(լրացվում են, եթե փաստացի քանակը զրոյից մեծ է)</small></strong><label>LOT համար<?=!empty($line['lot_control'])?' *':''?><input name="lot[<?=$lineId?>][lot_no]" maxlength="100" value="<?=h($line['counted_lot_no']??'')?>" placeholder="Օր.՝ LOT-2026-001" ></label><label>Պիտանի է մինչև<?=!empty($line['expiry_control'])?' *':''?><input name="lot[<?=$lineId?>][expires_on]" type="date" value="<?=h($line['counted_expires_on']??'')?>" ></label><label>Մատակարար<select name="lot[<?=$lineId?>][supplier_id]"><option value="">Նշված չէ</option><?php foreach($suppliers as $supplierId=>$supplierName):?><option value="<?=h($supplierId)?>" <?=($line['counted_supplier_id']??'')==$supplierId?'selected':''?>><?=h($supplierName)?></option><?php endforeach?></select></label><label>Պահեստային տեղ<input name="lot[<?=$lineId?>][bin_location]" maxlength="100" value="<?=h($line['counted_bin_location']??'')?>" placeholder="Օր.՝ A-01-02"></label><label>Միավորի արժեք, դրամ<input name="lot[<?=$lineId?>][unit_cost]" type="number" min="0" step="0.01" value="<?=h($line['counted_unit_cost']??'')?>" placeholder="Ապրանքի գնման գինը"></label></div><?php endif?></div><?php endforeach;endif?></div><div class="modal-actions"><?php if($lines):?><button class="secondary-button" name="action" value="inventory_count">Ներկայացնել հաստատման</button><?php else:?><button type="button" class="secondary-button" onclick="closeModal('count-<?=$r['id']?>')">Փակել</button><?php endif?></div></form></div><?php }function renderReturnModal(array $products,array $branches,array $suppliers,int $branch):void{?><div id="returns-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="return_create"><input type="hidden" name="return_page" value="returns"><div class="modal-head"><div><h2>Գրանցել ապրանքների վերադարձ</h2><p>Մեկ փաստաթղթով վերադարձեք մի քանի ապրանք․ խմբաքանակները կվերցվեն FEFO հերթով</p></div><button type="button" class="icon-button" onclick="closeModal('returns-modal')">×</button></div><div class="form-grid"><label>Վերադարձի տեսակ<select name="direction"><option value="branch_to_central">Մասնաճյուղ → Կենտրոն</option><?php if(!currentLocation()):?><option value="central_to_supplier">Կենտրոն → Մատակարար</option><?php endif?></select></label><label>Մասնաճյուղ<select name="from_location" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="from_location" value="<?=$branch?>"><?php endif?></label><label class="span-2">Մատակարար (մատակարարին վերադարձի դեպքում)<select name="supplier_id"><option value="">Ընտրել մատակարարին</option><?=optionRows($suppliers)?></select></label></div><div id="return-lines"><div class="return-line"><label>Ապրանք<select name="items[0][product_id]" required><option value="">Ընտրել ապրանքը</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Քանակ<input name="items[0][qty]" type="number" min="0.001" step="0.001" required></label></div></div><button type="button" class="text-link" onclick="addReturnLine()">＋ Ավելացնել ապրանք</button><label class="span-2">Պատճառ<textarea name="reason" required></textarea></label><div class="modal-actions"><button class="secondary-button" type="button" onclick="closeModal('returns-modal')">Չեղարկել</button><button class="primary-button">Գրանցել վերադարձը</button></div></form></div><?php }

function renderTransferModal(array $products,array $branches,int $branch):void{$targets=$branches;if($branch)unset($targets[$branch]);?><div id="transfers-modal" class="modal-backdrop" hidden><form method="post" class="modal-card wide-modal"><input type="hidden" name="_token" value="<?=h(token())?>"><input type="hidden" name="action" value="transfer_create"><input type="hidden" name="return_page" value="transfers"><div class="modal-head"><div><h2>Նոր տեղափոխման հարցում</h2><p>Մեկ փաստաթղթում ավելացրեք մի քանի ապրանք․ ուղարկելիս քանակը կհաշվարկվի FEFO հերթով</p></div><button type="button" class="icon-button" onclick="closeModal('transfers-modal')">×</button></div><div class="form-grid"><label>Ուղարկող պահեստ<select name="from_branch" <?=currentLocation()?'disabled':''?>><?=optionRows($branches,$branch)?></select><?php if(currentLocation()):?><input type="hidden" name="from_branch" value="<?=$branch?>"><?php endif?></label><label>Ստացող պահեստ<select name="to_branch" required><option value="">Ընտրել նպատակակետը</option><?=optionRows($targets)?></select></label></div><div id="transfer-lines"><div class="transfer-line"><label>Ապրանք<select name="items[0][product_id]" required><option value="">Ընտրել ապրանքը</option><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=h($p['code'].' · '.$p['name'])?></option><?php endforeach?></select></label><label>Քանակ<input name="items[0][qty]" type="number" min="0.001" step="0.001" required></label></div></div><button type="button" class="text-link" onclick="addTransferLine()">＋ Ավելացնել ապրանք</button><label class="span-2">Պատճառ<textarea name="reason" required></textarea></label><div class="modal-actions"><button type="button" class="secondary-button" onclick="closeModal('transfers-modal')">Չեղարկել</button><button class="primary-button">Ուղարկել հաստատման</button></div></form></div><?php }
